      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of an intervention (sodium bicarbonate), but no proposed mechanism of action is described in the retrieved evidence."
